    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        eventName: 'ACE_CHECKLIST_ITEM#ITEM_START_CLICKED',
        eventPayload: {
            propName: 'itemPayload',
            value: api.item
}
};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        eventName: 'ACE_CHECKLIST_ITEM#ITEM_UNDO_PERFORMED',
        eventPayload: {
            propName: 'itemPayload',
            value: api.item
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    var payload = api.state.payload;
    var itemValue = api.item.value;
    payload.items.forEach(
        function iter(item) {
            if (item.block_id == itemValue.block_id) {
                item.status = "start";
            }
            Array.isArray(item.children) && item.children.forEach(iter);
        }
    );
    return {
        propName: 'payload',
        value: {
            ...payload
        }
    };


}

