script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		eventName: 'ACE_CHECKLIST_ITEM#ITEM_SKIPPED',
		eventPayload: api.state.itemPayload
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    api.state.itemPayload.value.status = "skip";
    return {
        propName: 'itemPayload',
        value: { ...api.state.itemPayload
        }
    };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		eventName: 'ACE_CHECKLIST_ITEM#ITEM_CLICKED',
		eventPayload: api.state.itemPayload
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    api.state.itemPayload.value.status = "complete";
    return {
        propName: 'itemPayload',
        value: { ...api.state.itemPayload
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        blockId: api.state.itemPayload.parent.value.block_id,
        pageParams: null,
        includeChildBlocks: null
    };
}
